const uit = $input.first().json.output || $input.first().json;
const lijst = (uit.aanbiedingen || []).filter(a => a && a.product);
if (!lijst.length) {
  throw new Error('Geen Plus-aanbiedingen kunnen extraheren uit de pagina.');
}
const vandaag = new Date().toISOString().slice(0, 10);
const offers = lijst.map(a => ({
  winkel: 'Plus',
  product: String(a.product).trim(),
  prijs: String(a.prijs || '').trim(),
  korting: String(a.korting || '').trim(),
  geldig_tot: String(a.geldig_tot || '').trim(),
  opgehaald_op: vandaag,
}));
return [{ json: { winkel: 'Plus', aantal: offers.length, aanbiedingen: offers } }];

const inst = $('Instellingen aanbiedingen').first().json;
const chatId = String(inst.chatId || '').trim();
if (!chatId) {
  // Stil niets teruggeven is hier verwarrend: je ziet alleen een lege output en niet
  // waaróm. Zonder chat-id kan er sowieso geen bericht de deur uit, dus val op.
  throw new Error("Geen chat-id ingevuld. Open de node 'Instellingen aanbiedingen' en zet daar het chat-id van jullie groep neer (hetzelfde id als in allowedChatIds van de hoofdworkflow).");
}

function veiligJson(naam) {
  try { return $(naam).first().json; } catch (e) { return null; }
}
function veiligRijen(naam) {
  try {
    const rijen = $(naam).all().map(i => i.json);
    // Een leesnode die 'doorgaan bij fout' heeft, geeft bij een storing één item met .error
    if (rijen.length && rijen[0] && rijen[0].error != null) { return null; }
    return rijen;
  } catch (e) { return null; }
}

const ah = veiligJson('AH normaliseren');
const plus = veiligJson('Plus normaliseren');
const offers = [
  ...((ah && ah.aanbiedingen) || []),
  ...((plus && plus.aanbiedingen) || []),
];

// --- Woorden vergelijkbaar maken ------------------------------------------------
// Eerder vergeleken we hele regels ('1 liter halfvolle melk') letterlijk met de
// productnaam van een aanbieding, en telde een item pas mee als het twee keer
// exact zo op de lijst had gestaan. Allebei te streng: bijna geen twee regels zijn
// identiek, en een hele regel komt nooit letterlijk in een productnaam voor.
// Nu vergelijken we losse woorden, met dezelfde bewerking aan beide kanten.

// Woorden die niets zeggen over wát je koopt: hoeveelheden, verpakkingen, reclametaal.
const STOPWOORDEN = new Set([
  'de', 'het', 'een', 'van', 'voor', 'met', 'per', 'aan', 'bij', 'uit', 'ook', 'nog',
  'pak', 'pakje', 'zak', 'zakje', 'fles', 'flesje', 'blik', 'blikje', 'pot', 'potje',
  'bak', 'bakje', 'doos', 'doosje', 'krat', 'rol', 'rollen', 'tros', 'bos', 'bosje',
  'net', 'stuk', 'stuks', 'plak', 'plakken', 'punt', 'set', 'duo', 'multi',
  'gram', 'kilo', 'liter', 'milliliter',
  'grote', 'groot', 'kleine', 'klein', 'verse', 'vers', 'half', 'halve', 'halfvolle',
  'magere', 'mager', 'volle', 'mini', 'maxi', 'jong', 'jonge', 'oud', 'oude',
  'biologisch', 'biologische', 'scharrel',
  'korting', 'gratis', 'actie', 'aanbieding', 'voordeel', 'voordeelpak', 'bonus',
  'familiepak', 'alle', 'alles', 'alleen', 'alternatief', 'soort', 'soorten', 'varianten',
]);

// De stam hoeft taalkundig niet te kloppen: als 'tomaten' aan beide kanten op
// dezelfde 'tomat' uitkomt, matcht het. Daarom bewerken we boodschappen én
// productnamen met precies dezelfde functie.
function stam(woord) {
  if (woord.length > 5 && woord.endsWith('en')) { return woord.slice(0, -2); }
  if (woord.length > 4 && (woord.endsWith('s') || woord.endsWith('e'))) { return woord.slice(0, -1); }
  return woord;
}

function woorden(tekst) {
  return String(tekst || '')
    .toLowerCase()
    .replace(/[^a-zàâäçéèêëîïôöùûü]+/g, ' ') // cijfers en leestekens weg: '1l', '500gr', '2x'
    .split(' ')
    .filter(w => w.length >= 3 && !STOPWOORDEN.has(w));
}

// --- Wat zijn 'onze' producten? -------------------------------------------------
const gewicht = {};   // stam → hoe vaak we hem tegenkwamen
const origineel = {}; // stam → het woord zoals jullie het schrijven, voor in het bericht

function tel(tekst) {
  const gezien = new Set();
  for (const w of woorden(tekst)) {
    const s = stam(w);
    if (gezien.has(s)) { continue; } // 'melk melk' in één regel telt als één
    gezien.add(s);
    gewicht[s] = (gewicht[s] || 0) + 1;
    if (!origineel[s] || w.length < origineel[s].length) { origineel[s] = w; }
  }
}

// Boodschappen: afgevinkte items tellen gewoon mee, dat ís juist de historie.
const lijstRijen = (veiligRijen('Boodschappenhistorie ophalen') || []).filter(r => r && r.tekst);
// Staat er een boodschappenlijst tussen, gebruik dan alleen die — een klusjeslijst
// zegt niets over wat je in de supermarkt koopt.
const boodschappen = lijstRijen.filter(r => String(r.lijst || '').includes('boodschap'));
const bron = boodschappen.length ? boodschappen : lijstRijen;
for (const r of bron) { tel(r.tekst); }

// Gerechten: 'pasta pesto' levert 'pasta' en 'pesto' op.
const maaltijden = (veiligRijen('Maaltijdhistorie ophalen') || []).filter(r => r && r.gerecht);
for (const r of maaltijden) { tel(r.gerecht); }

// --- Aanbiedingen langs de zoektermen leggen ------------------------------------
const termen = Object.keys(gewicht);
const treffers = new Map();

for (const o of offers) {
  const productStammen = woorden(o.product).map(stam);
  let beste = null;
  for (const t of termen) {
    const raak = productStammen.some(ps =>
      ps === t
      // Nederlands plakt woorden aan elkaar: 'scharreleieren' bevat 'eier'.
      || (t.length >= 4 && ps.includes(t))
      // Korte woorden alleen vooraan, zodat 'kip' wel 'kipfilet' vangt maar niet zomaar iets.
      || (t.length === 3 && ps.startsWith(t))
    );
    if (raak && (beste === null || gewicht[t] > gewicht[beste])) { beste = t; }
  }
  if (beste === null) { continue; }
  const sleutel = `${o.winkel}|${o.product}`;
  const bestaand = treffers.get(sleutel);
  if (!bestaand || bestaand.score < gewicht[beste]) {
    treffers.set(sleutel, {
      winkel: o.winkel,
      product: o.product,
      korting: o.korting,
      term: origineel[beste],
      score: gewicht[beste],
    });
  }
}

// --- Indelen in categorieën -----------------------------------------------------
// De volgorde is die van een supermarktrondje en bepaalt ook de volgorde in het
// bericht. Het eerste rijtje dat past wint, dus specifieke categorieën staan boven
// algemene: 'kipfilet' hoort bij vlees, niet bij vleeswaren.
const CATEGORIEEN = [
  { naam: '🥦 Groente & fruit', woorden: [
    'groente', 'fruit', 'sla', 'salade', 'komkommer', 'tomaat', 'tomaten', 'paprika',
    'ui', 'uien', 'wortel', 'wortels', 'aardappel', 'aardappelen', 'broccoli', 'bloemkool',
    'spinazie', 'boerenkool', 'andijvie', 'prei', 'courgette', 'aubergine', 'champignon',
    'champignons', 'avocado', 'appel', 'appels', 'peer', 'peren', 'banaan', 'bananen',
    'sinaasappel', 'mandarijn', 'citroen', 'druif', 'druiven', 'aardbei', 'aardbeien',
    'blauwe bessen', 'meloen', 'ananas', 'kiwi', 'mango', 'bonen', 'sperziebonen',
    'worteltjes', 'radijs', 'bleekselderij', 'knoflook', 'gember', 'pompoen',
  ] },
  { naam: '🥩 Vlees & vis', woorden: [
    'kip', 'kipfilet', 'kipdij', 'kalkoen', 'rund', 'rundvlees', 'gehakt', 'biefstuk',
    'varken', 'varkens', 'speklap', 'spek', 'schnitzel', 'hamburger', 'hamburgers',
    'braadworst', 'shoarma', 'gyros', 'saté', 'vis', 'zalm', 'tonijn', 'kabeljauw',
    'garnaal', 'garnalen', 'mossel', 'mosselen', 'lam', 'kotelet', 'rookworst',
  ] },
  { naam: '🥛 Zuivel & eieren', woorden: [
    'melk', 'karnemelk', 'yoghurt', 'kwark', 'vla', 'pudding', 'toetje', 'room',
    'slagroom', 'boter', 'margarine', 'ei', 'eieren', 'eitjes', 'zuivel', 'drinkyoghurt',
  ] },
  { naam: '🧀 Kaas & beleg', woorden: [
    'kaas', 'ham', 'salami', 'worst', 'paté', 'rookvlees', 'beleg', 'smeerkaas',
    'hagelslag', 'pindakaas', 'jam', 'honing', 'chocopasta', 'vleeswaren',
  ] },
  { naam: '🍞 Brood & bakkerij', woorden: [
    'brood', 'broodje', 'bolletje', 'bolletjes', 'stokbrood', 'croissant', 'beschuit',
    'cracker', 'crackers', 'knäckebröd', 'taart', 'gebak', 'wrap', 'wraps', 'pita',
    'tortilla', 'bagel', 'ontbijtkoek',
  ] },
  { naam: '🍝 Voorraadkast', woorden: [
    'pasta', 'spaghetti', 'macaroni', 'penne', 'lasagne', 'noedel', 'noedels', 'rijst',
    'couscous', 'quinoa', 'linzen', 'saus', 'pastasaus', 'pesto', 'olie', 'olijfolie',
    'azijn', 'meel', 'bloem', 'suiker', 'zout', 'peper', 'kruiden', 'bouillon', 'soep',
    'mayonaise', 'ketchup', 'mosterd', 'curry', 'kerrie', 'kokosmelk', 'conserven',
    'muesli', 'cornflakes', 'havermout', 'ontbijtgranen',
  ] },
  { naam: '🧊 Diepvries', woorden: [
    'diepvries', 'pizza', 'frikandel', 'kroket', 'friet', 'patat', 'loempia',
    'vissticks', 'ijs', 'ijsjes',
  ] },
  { naam: '☕ Dranken', woorden: [
    'koffie', 'thee', 'cappuccino', 'espresso', 'sap', 'jus', 'cola', 'limonade',
    'frisdrank', 'water', 'spa', 'bier', 'wijn', 'smoothie', 'ranja',
  ] },
  { naam: '🍫 Snacks & snoep', woorden: [
    'chips', 'chocolade', 'chocola', 'snoep', 'koek', 'koekjes', 'biscuit', 'drop',
    'noten', 'pinda', 'pindas', 'popcorn', 'zoutjes', 'reep', 'repen', 'stroopwafel',
  ] },
  { naam: '🧻 Huishouden & verzorging', woorden: [
    'papier', 'toiletpapier', 'keukenpapier', 'wasmiddel', 'wasverzachter', 'afwasmiddel',
    'schoonmaak', 'allesreiniger', 'zeep', 'shampoo', 'douchegel', 'tandpasta',
    'tandenborstel', 'deodorant', 'luier', 'luiers', 'vuilniszak', 'vuilniszakken',
    'folie', 'doekjes', 'spons', 'sponzen', 'batterijen',
  ] },
];

function categorieVan(product) {
  const stammen = woorden(product).map(stam);
  for (const categorie of CATEGORIEEN) {
    for (const w of categorie.woorden) {
      const s = stam(w);
      if (stammen.some(ps => ps === s || (s.length >= 4 && ps.includes(s)))) {
        return categorie.naam;
      }
    }
  }
  return '🛒 Overig';
}

// Eerst per winkel, dan per categorie: zo lees je het als een boodschappenlijstje
// per winkel en zie je in één oogopslag waar je heen moet.
const volgorde = [...CATEGORIEEN.map(c => c.naam), '🛒 Overig'];
const winkels = [];
const perWinkel = new Map();
for (const t of treffers.values()) {
  const winkel = String(t.winkel || 'Onbekend');
  if (!perWinkel.has(winkel)) { perWinkel.set(winkel, new Map()); winkels.push(winkel); }
  const categorie = categorieVan(t.product);
  const vakken = perWinkel.get(winkel);
  if (!vakken.has(categorie)) { vakken.set(categorie, []); }
  vakken.get(categorie).push(t);
}

// --- Bericht opbouwen -----------------------------------------------------------
const blokken = [];
blokken.push(`🛒 Aanbiedingen opgehaald: ${ah ? ah.aantal + ' van AH' : 'AH mislukt'}, ${plus ? plus.aantal + ' van Plus' : 'Plus mislukt'}.`);

const aantalTreffers = treffers.size;
if (aantalTreffers) {
  blokken.push(`Dit past bij wat jullie kopen en koken (${aantalTreffers} ${aantalTreffers === 1 ? 'product' : 'producten'}):`);
  for (const winkel of winkels) {
    const vakken = perWinkel.get(winkel);
    const aantal = [...vakken.values()].reduce((n, rij) => n + rij.length, 0);
    const regels = [`🏪 ${winkel} (${aantal})`];
    for (const categorie of volgorde) {
      const rij = vakken.get(categorie);
      if (!rij || !rij.length) { continue; }
      rij.sort((a, b) => b.score - a.score || String(a.product).localeCompare(String(b.product)));
      regels.push(`${categorie}`);
      for (const t of rij) {
        regels.push(`• ${t.product}${t.korting ? ' — ' + t.korting : ''}  (${t.term})`);
      }
    }
    blokken.push(regels.join('\n'));
  }
} else if (!bron.length && !maaltijden.length) {
  blokken.push('Ik kan nog niet zien wat jullie vaak kopen: er staat nog niets op de boodschappenlijst en er zijn nog geen maaltijden gelogd.');
} else {
  blokken.push('Niets uit jullie boodschappen of gerechten is deze week in de aanbieding.');
}

blokken.push(`Gekeken naar ${bron.length} ${bron.length === 1 ? 'lijstitem' : 'lijstitems'} en ${maaltijden.length} ${maaltijden.length === 1 ? 'gerecht' : 'gerechten'}.\nVraag me gerust: "is er ... in de aanbieding?" of "wat eten we deze week?"`);

// Telegram kapt een bericht af boven de 4096 tekens. We knippen daarom zelf, het
// liefst tussen twee categorieën in, en geven meerdere items terug: de Telegram-node
// draait per item en stuurt er dan gewoon meerdere berichten achter elkaar.
const LIMIET = 3500;

function opsplitsen(blok) {
  if (blok.length <= LIMIET) { return [blok]; }
  const stukken = [];
  let huidig = '';
  for (const regel of blok.split('\n')) {
    if (huidig && (huidig.length + 1 + regel.length) > LIMIET) {
      stukken.push(huidig);
      huidig = regel;
    } else {
      huidig = huidig ? `${huidig}\n${regel}` : regel;
    }
  }
  if (huidig) { stukken.push(huidig); }
  return stukken;
}

const berichten = [];
let huidig = '';
for (const blok of blokken.flatMap(opsplitsen)) {
  if (huidig && (huidig.length + 2 + blok.length) > LIMIET) {
    berichten.push(huidig);
    huidig = blok;
  } else {
    huidig = huidig ? `${huidig}\n\n${blok}` : blok;
  }
}
if (huidig) { berichten.push(huidig); }

return berichten.map(tekst => ({ json: { chatId, tekst } }));

const inst = $('Instellingen aanbiedingen').first().json;
const chatId = String(inst.chatId || '').trim();
if (!chatId) { return []; }
const meldingen = $input.all().map(i => {
  const e = i.json.error;
  if (e && typeof e === 'object') { return e.message || JSON.stringify(e); }
  return String(e || i.json.message || 'onbekende fout');
});
return [{ json: { chatId, tekst: `⚠️ Het ophalen van de aanbiedingen is (deels) mislukt:\n${[...new Set(meldingen)].map(m => '• ' + m).join('\n')}\n\nZie de uitvoeringsdetails in n8n.` } }];
